import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.CodEvmtK.js";const p=JSON.parse('{"title":"Block reference","description":"","frontmatter":{},"headers":[],"relativePath":"blocks.md","filePath":"blocks.md","lastUpdated":1790948289000}'),r={name:"blocks.md"};function c(h,t,i,l,n,s){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="block-reference" tabindex="-1">Block reference <a class="header-anchor" href="#block-reference" aria-label="Permalink to &quot;Block reference&quot;">​</a></h1><p>Every entry in a screen&#39;s <code>blocks:</code> list is <code>{ type: &lt;name&gt;, ...props }</code>. Blocks marked <strong>children</strong> also take a <code>children:</code> list of blocks. A <code>text</code> value is a string, a number, or a translation object such as <code>{ en: &quot;Hello&quot;, de: &quot;Hallo&quot; }</code> (needs <code>languages:</code> in the spec).</p><h2 id="props-every-block-accepts" tabindex="-1">Props every block accepts <a class="header-anchor" href="#props-every-block-accepts" aria-label="Permalink to &quot;Props every block accepts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>tone</code></td><td><code>blue</code> | <code>green</code> | <code>yellow</code> | <code>red</code> | <code>purple</code> | <code>pink</code> | <code>orange</code> | <code>teal</code> | <code>gray</code></td><td>Colour this block and everything inside it: outlines, text and drawn shapes.</td></tr><tr><td><code>fill</code></td><td>boolean</td><td>Give the block a tinted background (uses <code>tone</code>, or a neutral tint).</td></tr></tbody></table><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><p>Blocks that list <code>go</code>, <code>toast</code>, <code>open</code> or <code>close</code> in their props are clickable (<code>button</code>, <code>card</code>, <code>avatar</code>, <code>link</code>, <code>nextbar</code>, nav and tab-bar items) and accept:</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>go</code></td><td>string</td><td>Id of the screen to open when clicked.</td></tr><tr><td><code>toast</code></td><td>text</td><td>Message shown in a toast when clicked.</td></tr><tr><td><code>open</code></td><td>string</td><td>Id of a <code>modal</code> block to open when clicked.</td></tr><tr><td><code>close</code></td><td>boolean</td><td>Close the modal this block is inside when clicked.</td></tr></tbody></table><h2 id="icons" tabindex="-1">Icons <a class="header-anchor" href="#icons" aria-label="Permalink to &quot;Icons&quot;">​</a></h2><p>Used by <code>icon</code>, <code>button.icon</code>, nav items and <code>tabbar</code>:</p><p><code>home</code> · <code>search</code> · <code>heart</code> · <code>comment</code> · <code>share</code> · <code>bookmark</code> · <code>plus</code> · <code>bell</code> · <code>user</code> · <code>users</code> · <code>mail</code> · <code>settings</code> · <code>camera</code> · <code>image</code> · <code>video</code> · <code>star</code> · <code>menu</code> · <code>more</code> · <code>close</code> · <code>check</code> · <code>arrow-right</code> · <code>arrow-left</code> · <code>chevron-down</code> · <code>chevron-right</code> · <code>play</code> · <code>pin</code> · <code>trash</code> · <code>edit</code> · <code>upload</code> · <code>download</code> · <code>lock</code> · <code>cart</code> · <code>chart</code> · <code>calendar</code> · <code>filter</code> · <code>info</code> · <code>send</code></p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><h3 id="stack-·-children" tabindex="-1"><code>stack</code> · children <a class="header-anchor" href="#stack-·-children" aria-label="Permalink to &quot;`stack` · children&quot;">​</a></h3><p>Vertical stack of blocks.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>center</code></td><td>boolean</td><td>Center the children horizontally.</td></tr></tbody></table><p>* required</p><h3 id="row-·-children" tabindex="-1"><code>row</code> · children <a class="header-anchor" href="#row-·-children" aria-label="Permalink to &quot;`row` · children&quot;">​</a></h3><p>Horizontal row that wraps on small screens. Images, videos, maps and charts in a row are 4:3 thumbnails of their height.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>between</code></td><td>boolean</td><td>Push the first and last child to opposite ends.</td></tr><tr><td><code>center</code></td><td>boolean</td><td>Center the children.</td></tr></tbody></table><p>* required</p><h3 id="grid-·-children" tabindex="-1"><code>grid</code> · children <a class="header-anchor" href="#grid-·-children" aria-label="Permalink to &quot;`grid` · children&quot;">​</a></h3><p>Equal-width columns. Collapses to one column on phones.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>cols</code></td><td>number</td><td>Number of columns (default 2).</td></tr></tbody></table><p>* required</p><h3 id="card-·-children" tabindex="-1"><code>card</code> · children <a class="header-anchor" href="#card-·-children" aria-label="Permalink to &quot;`card` · children&quot;">​</a></h3><p>Hand-drawn box around related blocks. Clickable when <code>go</code> is set.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>title</code></td><td>text</td><td>Small heading at the top of the card.</td></tr><tr><td><code>dash</code></td><td>boolean</td><td>No fill (a lighter, secondary card).</td></tr><tr><td><code>center</code></td><td>boolean</td><td>Center the content horizontally.</td></tr><tr><td><code>elevation</code></td><td>number</td><td>Shadow layers, 1 to 5 (default 1).</td></tr><tr><td><code>go</code></td><td>string</td><td>Id of the screen to open when clicked.</td></tr><tr><td><code>toast</code></td><td>text</td><td>Message shown in a toast when clicked.</td></tr><tr><td><code>open</code></td><td>string</td><td>Id of a <code>modal</code> block to open when clicked.</td></tr><tr><td><code>close</code></td><td>boolean</td><td>Close the modal this block is inside when clicked.</td></tr></tbody></table><p>* required</p><h3 id="accordion" tabindex="-1"><code>accordion</code> <a class="header-anchor" href="#accordion" aria-label="Permalink to &quot;`accordion`&quot;">​</a></h3><p>Collapsible sections (FAQ, filters, settings groups).</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>items</code> *</td><td>list of <code>{ label, children }</code></td><td>List of <code>{ label, children }</code>.</td></tr><tr><td><code>open</code></td><td>number</td><td>Index of the section open at first (default: all closed).</td></tr></tbody></table><p>* required</p><h3 id="device-·-children" tabindex="-1"><code>device</code> · children <a class="header-anchor" href="#device-·-children" aria-label="Permalink to &quot;`device` · children&quot;">​</a></h3><p>Wrap screens in a phone, tablet or browser frame. Ideal for mobile-app and responsive sketches.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>kind</code></td><td><code>phone</code> | <code>tablet</code> | <code>browser</code></td><td>Frame type (default <code>phone</code>).</td></tr><tr><td><code>title</code></td><td>text</td><td>Address shown in the browser bar.</td></tr></tbody></table><p>* required</p><h3 id="divider" tabindex="-1"><code>divider</code> <a class="header-anchor" href="#divider" aria-label="Permalink to &quot;`divider`&quot;">​</a></h3><p>Hand-drawn horizontal line.</p><h3 id="spacer" tabindex="-1"><code>spacer</code> <a class="header-anchor" href="#spacer" aria-label="Permalink to &quot;`spacer`&quot;">​</a></h3><p>Empty vertical space.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>h</code></td><td>number</td><td>Height in px (default 16).</td></tr></tbody></table><p>* required</p><h2 id="text" tabindex="-1">Text <a class="header-anchor" href="#text" aria-label="Permalink to &quot;Text&quot;">​</a></h2><h3 id="h1" tabindex="-1"><code>h1</code> <a class="header-anchor" href="#h1" aria-label="Permalink to &quot;`h1`&quot;">​</a></h3><p>Level 1 heading.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>text</code> *</td><td>text</td><td>Heading text.</td></tr></tbody></table><p>* required</p><h3 id="h2" tabindex="-1"><code>h2</code> <a class="header-anchor" href="#h2" aria-label="Permalink to &quot;`h2`&quot;">​</a></h3><p>Level 2 heading.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>text</code> *</td><td>text</td><td>Heading text.</td></tr></tbody></table><p>* required</p><h3 id="h3" tabindex="-1"><code>h3</code> <a class="header-anchor" href="#h3" aria-label="Permalink to &quot;`h3`&quot;">​</a></h3><p>Level 3 heading.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>text</code> *</td><td>text</td><td>Heading text.</td></tr></tbody></table><p>* required</p><h3 id="text-1" tabindex="-1"><code>text</code> <a class="header-anchor" href="#text-1" aria-label="Permalink to &quot;`text`&quot;">​</a></h3><p>Paragraph. A bare string in a <code>children</code> list is shorthand for this block.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>text</code> *</td><td>text</td><td>Paragraph text.</td></tr><tr><td><code>muted</code></td><td>boolean</td><td>Grey, smaller text.</td></tr><tr><td><code>bold</code></td><td>boolean</td><td>Bold text.</td></tr></tbody></table><p>* required</p><h3 id="list" tabindex="-1"><code>list</code> <a class="header-anchor" href="#list" aria-label="Permalink to &quot;`list`&quot;">​</a></h3><p>Bulleted list.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>items</code> *</td><td>list of text</td><td>List items.</td></tr></tbody></table><p>* required</p><h3 id="note" tabindex="-1"><code>note</code> <a class="header-anchor" href="#note" aria-label="Permalink to &quot;`note`&quot;">​</a></h3><p>Yellow sticky-note annotation. Use it for behaviour a sketch cannot show.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>text</code> *</td><td>text</td><td>Note text.</td></tr></tbody></table><p>* required</p><h3 id="badge" tabindex="-1"><code>badge</code> <a class="header-anchor" href="#badge" aria-label="Permalink to &quot;`badge`&quot;">​</a></h3><p>Small status pill.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>text</code> *</td><td>text</td><td>Badge text.</td></tr><tr><td><code>status</code></td><td><code>on</code> | <code>wait</code> | <code>off</code></td><td>Colour: <code>on</code> green, <code>wait</code> orange, <code>off</code> grey.</td></tr></tbody></table><p>* required</p><h2 id="content" tabindex="-1">Content <a class="header-anchor" href="#content" aria-label="Permalink to &quot;Content&quot;">​</a></h2><h3 id="icon" tabindex="-1"><code>icon</code> <a class="header-anchor" href="#icon" aria-label="Permalink to &quot;`icon`&quot;">​</a></h3><p>Hand-drawn icon.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code> *</td><td><code>home</code> | <code>search</code> | <code>heart</code> | <code>comment</code> | <code>share</code> | <code>bookmark</code> | <code>plus</code> | <code>bell</code> | <code>user</code> | <code>users</code> | <code>mail</code> | <code>settings</code> | <code>camera</code> | <code>image</code> | <code>video</code> | <code>star</code> | <code>menu</code> | <code>more</code> | <code>close</code> | <code>check</code> | <code>arrow-right</code> | <code>arrow-left</code> | <code>chevron-down</code> | <code>chevron-right</code> | <code>play</code> | <code>pin</code> | <code>trash</code> | <code>edit</code> | <code>upload</code> | <code>download</code> | <code>lock</code> | <code>cart</code> | <code>chart</code> | <code>calendar</code> | <code>filter</code> | <code>info</code> | <code>send</code></td><td>Icon name.</td></tr><tr><td><code>size</code></td><td>number</td><td>Size in px (default 22).</td></tr><tr><td><code>filled</code></td><td>boolean</td><td>Solid instead of outline (heart, star, bookmark…).</td></tr></tbody></table><p>* required</p><h3 id="avatar" tabindex="-1"><code>avatar</code> <a class="header-anchor" href="#avatar" aria-label="Permalink to &quot;`avatar`&quot;">​</a></h3><p>Round profile picture with an optional name and sub-line. Clickable.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>text</td><td>Bold name next to the picture.</td></tr><tr><td><code>sub</code></td><td>text</td><td>Smaller line under the name.</td></tr><tr><td><code>size</code></td><td>number</td><td>Picture size in px (default 44).</td></tr><tr><td><code>go</code></td><td>string</td><td>Id of the screen to open when clicked.</td></tr><tr><td><code>toast</code></td><td>text</td><td>Message shown in a toast when clicked.</td></tr><tr><td><code>open</code></td><td>string</td><td>Id of a <code>modal</code> block to open when clicked.</td></tr><tr><td><code>close</code></td><td>boolean</td><td>Close the modal this block is inside when clicked.</td></tr></tbody></table><p>* required</p><h3 id="hero-·-children" tabindex="-1"><code>hero</code> · children <a class="header-anchor" href="#hero-·-children" aria-label="Permalink to &quot;`hero` · children&quot;">​</a></h3><p>Big headline block for landing pages. Put call-to-action buttons (or an image) in <code>children</code>.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>title</code> *</td><td>text</td><td>Headline.</td></tr><tr><td><code>text</code></td><td>text</td><td>Supporting sentence.</td></tr><tr><td><code>align</code></td><td><code>left</code> | <code>center</code></td><td>Text alignment (default <code>center</code>).</td></tr></tbody></table><p>* required</p><h3 id="stat" tabindex="-1"><code>stat</code> <a class="header-anchor" href="#stat" aria-label="Permalink to &quot;`stat`&quot;">​</a></h3><p>Number card for dashboards: label, big value and a change indicator.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>label</code> *</td><td>text</td><td>What is measured.</td></tr><tr><td><code>value</code> *</td><td>text</td><td>The number.</td></tr><tr><td><code>delta</code></td><td>text</td><td>Change, e.g. <code>+8%</code>.</td></tr><tr><td><code>trend</code></td><td><code>up</code> | <code>down</code> | <code>flat</code></td><td>Colours the change: <code>up</code> green, <code>down</code> orange, <code>flat</code> grey (default <code>up</code>).</td></tr></tbody></table><p>* required</p><h3 id="rating" tabindex="-1"><code>rating</code> <a class="header-anchor" href="#rating" aria-label="Permalink to &quot;`rating`&quot;">​</a></h3><p>Star rating.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>value</code></td><td>number</td><td>Filled stars (default 4).</td></tr><tr><td><code>max</code></td><td>number</td><td>Total stars (default 5).</td></tr><tr><td><code>text</code></td><td>text</td><td>Text after the stars, e.g. <code>(128 reviews)</code>.</td></tr></tbody></table><p>* required</p><h3 id="link" tabindex="-1"><code>link</code> <a class="header-anchor" href="#link" aria-label="Permalink to &quot;`link`&quot;">​</a></h3><p>Underlined text link.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>text</code> *</td><td>text</td><td>Link text.</td></tr><tr><td><code>go</code></td><td>string</td><td>Id of the screen to open when clicked.</td></tr><tr><td><code>toast</code></td><td>text</td><td>Message shown in a toast when clicked.</td></tr><tr><td><code>open</code></td><td>string</td><td>Id of a <code>modal</code> block to open when clicked.</td></tr><tr><td><code>close</code></td><td>boolean</td><td>Close the modal this block is inside when clicked.</td></tr></tbody></table><p>* required</p><h2 id="media" tabindex="-1">Media <a class="header-anchor" href="#media" aria-label="Permalink to &quot;Media&quot;">​</a></h2><h3 id="image" tabindex="-1"><code>image</code> <a class="header-anchor" href="#image" aria-label="Permalink to &quot;`image`&quot;">​</a></h3><p>Image placeholder: hand-drawn box with a cross. Use <code>round</code> for avatars.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>h</code></td><td>number</td><td>Height in px.</td></tr><tr><td><code>label</code></td><td>text</td><td>Caption centered in the box.</td></tr><tr><td><code>round</code></td><td>boolean</td><td>Draw a circle instead of a box.</td></tr></tbody></table><p>* required</p><h3 id="map" tabindex="-1"><code>map</code> <a class="header-anchor" href="#map" aria-label="Permalink to &quot;`map`&quot;">​</a></h3><p>Map placeholder with a pin.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>h</code></td><td>number</td><td>Height in px.</td></tr><tr><td><code>label</code></td><td>text</td><td>Caption centered in the box.</td></tr></tbody></table><p>* required</p><h3 id="box" tabindex="-1"><code>box</code> <a class="header-anchor" href="#box" aria-label="Permalink to &quot;`box`&quot;">​</a></h3><p>Generic hand-drawn box, for ads, embeds, anything else.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>h</code></td><td>number</td><td>Height in px.</td></tr><tr><td><code>label</code></td><td>text</td><td>Caption centered in the box.</td></tr></tbody></table><p>* required</p><h3 id="video" tabindex="-1"><code>video</code> <a class="header-anchor" href="#video" aria-label="Permalink to &quot;`video`&quot;">​</a></h3><p>Video placeholder with a play button.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>h</code></td><td>number</td><td>Height in px.</td></tr><tr><td><code>label</code></td><td>text</td><td>Caption centered in the box.</td></tr></tbody></table><p>* required</p><h3 id="carousel" tabindex="-1"><code>carousel</code> <a class="header-anchor" href="#carousel" aria-label="Permalink to &quot;`carousel`&quot;">​</a></h3><p>Swipeable gallery: image placeholder with arrows and page dots.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>h</code></td><td>number</td><td>Height in px.</td></tr><tr><td><code>label</code></td><td>text</td><td>Caption centered in the box.</td></tr><tr><td><code>count</code></td><td>number</td><td>Number of slides shown as dots (default 4).</td></tr></tbody></table><p>* required</p><h3 id="dropzone" tabindex="-1"><code>dropzone</code> <a class="header-anchor" href="#dropzone" aria-label="Permalink to &quot;`dropzone`&quot;">​</a></h3><p>Dashed upload area with an arrow.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>h</code></td><td>number</td><td>Height in px.</td></tr><tr><td><code>label</code></td><td>text</td><td>Caption centered in the box.</td></tr></tbody></table><p>* required</p><h3 id="chart" tabindex="-1"><code>chart</code> <a class="header-anchor" href="#chart" aria-label="Permalink to &quot;`chart`&quot;">​</a></h3><p>Hand-drawn chart with sample data. It shows where a chart goes and what kind it is.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>kind</code></td><td><code>line</code> | <code>area</code> | <code>bar</code> | <code>pie</code> | <code>donut</code></td><td>Chart type (default <code>line</code>).</td></tr><tr><td><code>h</code></td><td>number</td><td>Height in px.</td></tr><tr><td><code>values</code></td><td>list of numbers</td><td>Your own data points. Leave out for sample data.</td></tr><tr><td><code>label</code></td><td>text</td><td>Caption in the corner.</td></tr></tbody></table><p>* required</p><h2 id="forms" tabindex="-1">Forms <a class="header-anchor" href="#forms" aria-label="Permalink to &quot;Forms&quot;">​</a></h2><h3 id="input" tabindex="-1"><code>input</code> <a class="header-anchor" href="#input" aria-label="Permalink to &quot;`input`&quot;">​</a></h3><p>Single-line text field.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>label</code></td><td>text</td><td>Label shown above the control.</td></tr><tr><td><code>placeholder</code></td><td>text</td><td>Placeholder text.</td></tr><tr><td><code>value</code></td><td>text</td><td>Pre-filled value.</td></tr><tr><td><code>inputType</code></td><td>string</td><td>HTML input type: <code>text</code>, <code>email</code>, <code>password</code>, <code>number</code>…</td></tr><tr><td><code>disabled</code></td><td>boolean</td><td>Grey out the field.</td></tr></tbody></table><p>* required</p><h3 id="search" tabindex="-1"><code>search</code> <a class="header-anchor" href="#search" aria-label="Permalink to &quot;`search`&quot;">​</a></h3><p>Search field with a magnifier.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>placeholder</code></td><td>text</td><td>Placeholder text.</td></tr></tbody></table><p>* required</p><h3 id="textarea" tabindex="-1"><code>textarea</code> <a class="header-anchor" href="#textarea" aria-label="Permalink to &quot;`textarea`&quot;">​</a></h3><p>Multi-line text field.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>label</code></td><td>text</td><td>Label shown above the control.</td></tr><tr><td><code>placeholder</code></td><td>text</td><td>Placeholder text.</td></tr><tr><td><code>rows</code></td><td>number</td><td>Visible rows (default 3).</td></tr></tbody></table><p>* required</p><h3 id="select" tabindex="-1"><code>select</code> <a class="header-anchor" href="#select" aria-label="Permalink to &quot;`select`&quot;">​</a></h3><p>Dropdown.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>label</code></td><td>text</td><td>Label shown above the control.</td></tr><tr><td><code>options</code> *</td><td>list of text</td><td>Choices.</td></tr><tr><td><code>selected</code></td><td>number</td><td>Index of the pre-selected option (default 0).</td></tr></tbody></table><p>* required</p><h3 id="checkbox" tabindex="-1"><code>checkbox</code> <a class="header-anchor" href="#checkbox" aria-label="Permalink to &quot;`checkbox`&quot;">​</a></h3><p>Checkbox with a label.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>label</code> *</td><td>text</td><td>Label shown above the control.</td></tr><tr><td><code>checked</code></td><td>boolean</td><td>Start ticked.</td></tr></tbody></table><p>* required</p><h3 id="toggle" tabindex="-1"><code>toggle</code> <a class="header-anchor" href="#toggle" aria-label="Permalink to &quot;`toggle`&quot;">​</a></h3><p>On/off switch with a label.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>label</code> *</td><td>text</td><td>Label shown above the control.</td></tr><tr><td><code>checked</code></td><td>boolean</td><td>Start switched on.</td></tr></tbody></table><p>* required</p><h3 id="radio" tabindex="-1"><code>radio</code> <a class="header-anchor" href="#radio" aria-label="Permalink to &quot;`radio`&quot;">​</a></h3><p>Radio group.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>label</code></td><td>text</td><td>Label shown above the control.</td></tr><tr><td><code>options</code> *</td><td>list of text</td><td>Choices.</td></tr><tr><td><code>selected</code></td><td>number</td><td>Index of the pre-selected option (default 0).</td></tr></tbody></table><p>* required</p><h3 id="slider" tabindex="-1"><code>slider</code> <a class="header-anchor" href="#slider" aria-label="Permalink to &quot;`slider`&quot;">​</a></h3><p>Range slider.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>label</code></td><td>text</td><td>Label shown above the control.</td></tr><tr><td><code>value</code></td><td>number</td><td>Start position, 0 to 100 (default 30).</td></tr></tbody></table><p>* required</p><h2 id="actions-1" tabindex="-1">Actions <a class="header-anchor" href="#actions-1" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><h3 id="button" tabindex="-1"><code>button</code> <a class="header-anchor" href="#button" aria-label="Permalink to &quot;`button`&quot;">​</a></h3><p>Button, optionally with an icon. Navigates with <code>go</code>, opens a <code>modal</code> with <code>open</code>, shows a message with <code>toast</code>.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>label</code></td><td>text</td><td>Button text. Leave out for an icon-only button.</td></tr><tr><td><code>icon</code></td><td><code>home</code> | <code>search</code> | <code>heart</code> | <code>comment</code> | <code>share</code> | <code>bookmark</code> | <code>plus</code> | <code>bell</code> | <code>user</code> | <code>users</code> | <code>mail</code> | <code>settings</code> | <code>camera</code> | <code>image</code> | <code>video</code> | <code>star</code> | <code>menu</code> | <code>more</code> | <code>close</code> | <code>check</code> | <code>arrow-right</code> | <code>arrow-left</code> | <code>chevron-down</code> | <code>chevron-right</code> | <code>play</code> | <code>pin</code> | <code>trash</code> | <code>edit</code> | <code>upload</code> | <code>download</code> | <code>lock</code> | <code>cart</code> | <code>chart</code> | <code>calendar</code> | <code>filter</code> | <code>info</code> | <code>send</code></td><td>Icon shown before the label.</td></tr><tr><td><code>primary</code></td><td>boolean</td><td>Heavier border: the main action on the screen.</td></tr><tr><td><code>disabled</code></td><td>boolean</td><td>Grey out the button.</td></tr><tr><td><code>go</code></td><td>string</td><td>Id of the screen to open when clicked.</td></tr><tr><td><code>toast</code></td><td>text</td><td>Message shown in a toast when clicked.</td></tr><tr><td><code>open</code></td><td>string</td><td>Id of a <code>modal</code> block to open when clicked.</td></tr><tr><td><code>close</code></td><td>boolean</td><td>Close the modal this block is inside when clicked.</td></tr></tbody></table><p>* required</p><h3 id="chips" tabindex="-1"><code>chips</code> <a class="header-anchor" href="#chips" aria-label="Permalink to &quot;`chips`&quot;">​</a></h3><p>Filter pills. Clicking one selects it and shows a “Results updated” toast.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>options</code> *</td><td>list of text</td><td>Pill labels.</td></tr><tr><td><code>active</code></td><td>number</td><td>Index of the selected pill (default 0).</td></tr></tbody></table><p>* required</p><h3 id="tabs" tabindex="-1"><code>tabs</code> <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;`tabs`&quot;">​</a></h3><p>Tab strip. Each tab has its own list of blocks.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>tabs</code> *</td><td>list of <code>{ label, children }</code></td><td>List of <code>{ label, children }</code>.</td></tr></tbody></table><p>* required</p><h3 id="nextbar" tabindex="-1"><code>nextbar</code> <a class="header-anchor" href="#nextbar" aria-label="Permalink to &quot;`nextbar`&quot;">​</a></h3><p>“Next →” strip at the bottom of a screen. Hidden in the PDF.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>label</code></td><td>text</td><td>Bold lead-in (default “Next →”).</td></tr><tr><td><code>text</code></td><td>text</td><td>What happens next.</td></tr><tr><td><code>button</code></td><td>text</td><td>Button text (default “Continue →”).</td></tr><tr><td><code>go</code></td><td>string</td><td>Id of the screen to open when clicked.</td></tr><tr><td><code>toast</code></td><td>text</td><td>Message shown in a toast when clicked.</td></tr><tr><td><code>open</code></td><td>string</td><td>Id of a <code>modal</code> block to open when clicked.</td></tr><tr><td><code>close</code></td><td>boolean</td><td>Close the modal this block is inside when clicked.</td></tr></tbody></table><p>* required</p><h2 id="navigation" tabindex="-1">Navigation <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;Navigation&quot;">​</a></h2><h3 id="breadcrumb" tabindex="-1"><code>breadcrumb</code> <a class="header-anchor" href="#breadcrumb" aria-label="Permalink to &quot;`breadcrumb`&quot;">​</a></h3><p>Path to the current page. The last item is the current one.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>items</code> *</td><td>list of text</td><td>Path segments.</td></tr></tbody></table><p>* required</p><h3 id="pagination" tabindex="-1"><code>pagination</code> <a class="header-anchor" href="#pagination" aria-label="Permalink to &quot;`pagination`&quot;">​</a></h3><p>Previous / page numbers / next.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>pages</code></td><td>number</td><td>Number of pages (default 5).</td></tr><tr><td><code>active</code></td><td>number</td><td>Current page, starting at 1 (default 1).</td></tr></tbody></table><p>* required</p><h3 id="steps" tabindex="-1"><code>steps</code> <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;`steps`&quot;">​</a></h3><p>Numbered progress through a multi-step flow (checkout, onboarding).</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>items</code> *</td><td>list of text</td><td>Step names.</td></tr><tr><td><code>active</code></td><td>number</td><td>Index of the current step, starting at 0 (default 0).</td></tr></tbody></table><p>* required</p><h3 id="tabbar" tabindex="-1"><code>tabbar</code> <a class="header-anchor" href="#tabbar" aria-label="Permalink to &quot;`tabbar`&quot;">​</a></h3><p>Bottom tab bar of a mobile app: icons with small labels.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>items</code> *</td><td>list of <code>{ icon, label, go, toast, open }</code></td><td>List of <code>{ icon, label, go, toast, open }</code>.</td></tr><tr><td><code>active</code></td><td>number</td><td>Index of the highlighted item (default 0).</td></tr></tbody></table><p>* required</p><h2 id="feedback" tabindex="-1">Feedback <a class="header-anchor" href="#feedback" aria-label="Permalink to &quot;Feedback&quot;">​</a></h2><h3 id="alert" tabindex="-1"><code>alert</code> <a class="header-anchor" href="#alert" aria-label="Permalink to &quot;`alert`&quot;">​</a></h3><p>Banner for information, success, warnings and errors.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>text</code> *</td><td>text</td><td>Message.</td></tr><tr><td><code>title</code></td><td>text</td><td>Bold first line.</td></tr><tr><td><code>kind</code></td><td><code>info</code> | <code>success</code> | <code>warning</code> | <code>error</code></td><td>Type and colour (default <code>info</code>).</td></tr></tbody></table><p>* required</p><h3 id="progress" tabindex="-1"><code>progress</code> <a class="header-anchor" href="#progress" aria-label="Permalink to &quot;`progress`&quot;">​</a></h3><p>Progress bar.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>value</code> *</td><td>number</td><td>Percent complete, 0 to 100.</td></tr><tr><td><code>label</code></td><td>text</td><td>Caption above the bar.</td></tr></tbody></table><p>* required</p><h2 id="overlays" tabindex="-1">Overlays <a class="header-anchor" href="#overlays" aria-label="Permalink to &quot;Overlays&quot;">​</a></h2><h3 id="modal-·-children" tabindex="-1"><code>modal</code> · children <a class="header-anchor" href="#modal-·-children" aria-label="Permalink to &quot;`modal` · children&quot;">​</a></h3><p>Dialog that opens over the screen when a button, card or link has <code>open: &lt;id&gt;</code>. Close with a <code>close: true</code> button, the X, or a click outside.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code> *</td><td>string</td><td>Unique id; other blocks use it in <code>open:</code>.</td></tr><tr><td><code>title</code></td><td>text</td><td>Heading of the dialog.</td></tr><tr><td><code>width</code></td><td><code>narrow</code> | <code>medium</code> | <code>wide</code></td><td>Dialog width (default <code>medium</code>).</td></tr></tbody></table><p>* required</p><h2 id="data" tabindex="-1">Data <a class="header-anchor" href="#data" aria-label="Permalink to &quot;Data&quot;">​</a></h2><h3 id="table" tabindex="-1"><code>table</code> <a class="header-anchor" href="#table" aria-label="Permalink to &quot;`table`&quot;">​</a></h3><p>Table. A cell is text or a block (e.g. <code>badge</code>, <code>button</code>). A row can be <code>{ cells, go }</code> to make it clickable.</p><table tabindex="0"><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>columns</code> *</td><td>list of text</td><td>Column headings.</td></tr><tr><td><code>rows</code> *</td><td>list of rows</td><td>List of rows: <code>[cell, cell]</code> or <code>{ cells: [...], go: screenId }</code>.</td></tr></tbody></table><p>* required</p>',210)])])}const u=e(r,[["render",c]]);export{p as __pageData,u as default};
